import{_ as s,o as a,c as t,a0 as i}from"./chunks/framework.jwovEGr5.js";const g=JSON.parse('{"title":"Cross-Device Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"CROSS_DEVICE_DEPLOY.md","filePath":"CROSS_DEVICE_DEPLOY.md"}'),n={name:"CROSS_DEVICE_DEPLOY.md"};function r(l,e,o,h,d,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="cross-device-deployment" tabindex="-1">Cross-Device Deployment <a class="header-anchor" href="#cross-device-deployment" aria-label="Permalink to &quot;Cross-Device Deployment&quot;">​</a></h1><p>sharecli&#39;s <code>fleet</code> subcommand coordinates agent workloads across multiple machines. Each device registers into a shared registry over <a href="https://nats.io" target="_blank" rel="noreferrer">NATS</a>, advertising its hostname, OS, and free execution slots so a coordinator can place work where capacity (and thermal headroom) exists.</p><p>This guide covers installing sharecli on each device, registering it into the fleet, and reading fleet status. The NATS transport for <code>fleet register</code> / <code>fleet status</code> is under active development; the commands are wired end-to-end but publish against a stub backend until the runtime wiring lands.</p><h2 id="what-the-fleet-does" tabindex="-1">What the fleet does <a class="header-anchor" href="#what-the-fleet-does" aria-label="Permalink to &quot;What the fleet does&quot;">​</a></h2><ul><li><strong>Device registry</strong> — each device publishes a <code>DeviceRecord</code> (<code>device_id</code>, <code>hostname</code>, <code>os</code>, <code>available_slots</code>) to the NATS subject <code>sharecli.fleet.devices.{device_id}</code>.</li><li><strong>Thermal governor</strong> — before accepting new work, a device consults its thermal governor so an overheating machine is not scheduled into the red.</li><li><strong>Coordinator</strong> — a NATS broker any device can reach; it is the rendezvous point for registration and (later) work placement.</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ol><li><p><strong>A reachable NATS server</strong> — one broker that every device can connect to. Install locally with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nats-server</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux (or download a release binary from nats.io)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com/nats-io/nats-server/v2@latest</span></span></code></pre></div><p>Start it (defaults to <code>0.0.0.0:4222</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nats-server</span></span></code></pre></div><p>For a multi-machine fleet, run the broker on a host every device can route to and use <code>nats://&lt;host&gt;:4222</code> as the coordinator address below.</p></li><li><p><strong>sharecli installed on every device</strong> (see next section).</p></li><li><p><strong>Network reachability</strong> — TCP <code>4222</code> open from each device to the broker.</p></li></ol><h2 id="install-sharecli-on-each-device" tabindex="-1">Install sharecli on each device <a class="header-anchor" href="#install-sharecli-on-each-device" aria-label="Permalink to &quot;Install sharecli on each device&quot;">​</a></h2><p>Build from source (Rust toolchain required — <a href="https://rustup.rs" target="_blank" rel="noreferrer">https://rustup.rs</a>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/KooshaPari/sharecli</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sharecli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># binary at target/release/sharecli — copy onto PATH, e.g.:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0755</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/release/sharecli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/sharecli</span></span></code></pre></div><p>Verify:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sharecli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sharecli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fleet</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><h2 id="register-a-device" tabindex="-1">Register a device <a class="header-anchor" href="#register-a-device" aria-label="Permalink to &quot;Register a device&quot;">​</a></h2><p>Run this once per device. <code>--name</code> defaults to <code>local</code>; <code>--coordinator</code> defaults to <code>nats://localhost:4222</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># local broker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sharecli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fleet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> register</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># named device against a remote coordinator</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sharecli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fleet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> register</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worker-mini</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --coordinator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nats://10.0.0.5:4222</span></span></code></pre></div><p>Expected output:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Registering device &#39;worker-mini&#39; with coordinator &#39;nats://10.0.0.5:4222&#39;</span></span>
<span class="line"><span>(Fleet NATS wiring pending — stub)</span></span></code></pre></div><h2 id="check-fleet-status" tabindex="-1">Check fleet status <a class="header-anchor" href="#check-fleet-status" aria-label="Permalink to &quot;Check fleet status&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sharecli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fleet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>Expected output:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thermal governor: ready (polling pending backend wiring)</span></span>
<span class="line"><span>Fleet registry: not connected (run \`sharecli fleet register\` first)</span></span></code></pre></div><p><code>fleet status</code> reports the local thermal governor state and whether this device is attached to a registry.</p><h2 id="thermal-governor-behavior" tabindex="-1">Thermal governor behavior <a class="header-anchor" href="#thermal-governor-behavior" aria-label="Permalink to &quot;Thermal governor behavior&quot;">​</a></h2><p>The thermal governor gates new work by machine temperature so a hot device is not pushed further into throttling. It reports one of three levels:</p><table tabindex="0"><thead><tr><th>Level</th><th>Meaning</th><th>Scheduling effect</th></tr></thead><tbody><tr><td>Green</td><td>Normal temperature/headroom</td><td>Accept new work</td></tr><tr><td>Yellow</td><td>Elevated — approaching limits</td><td>Slow down; prefer cooler devices</td></tr><tr><td>Red</td><td>Hot — at or over thermal limit</td><td>Refuse new work until it cools</td></tr></tbody></table><p>Platform sourcing:</p><ul><li><strong>macOS</strong> — reads OS thermal-pressure signals (<code>kern.memorystatus</code>/thermal-pressure APIs) rather than raw temperatures. Note: low swap-free alone is <em>not</em> a thermal signal on macOS; pressure level is the correct metric.</li><li><strong>Linux</strong> — reads thermal zones under <code>/sys/class/thermal/thermal_zone*</code>.</li></ul><p>Thermal polling is stubbed in the current release; <code>fleet status</code> confirms the governor is wired and will surface live levels once backend polling lands.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong><code>sharecli: command not found</code></strong> — the release binary is not on <code>PATH</code>. Re-run the <code>install</code> step or add <code>~/.local/bin</code> to <code>PATH</code>.</li><li><strong>Cannot reach the coordinator</strong> — confirm the broker is running (<code>nats-server</code>) and TCP <code>4222</code> is open from the device to the broker host. Test with <code>nc -vz &lt;host&gt; 4222</code>.</li><li><strong>Device does not appear in the registry</strong> — registration currently publishes against a stub backend; live registry listing lands with the NATS runtime wiring. Until then, <code>fleet status</code> shows <code>not connected</code>.</li><li><strong>Wrong device name</strong> — <code>--name</code> is free-form; re-run <code>fleet register</code> with the corrected <code>--name</code>.</li><li><strong>Thermal level always shows pending</strong> — expected in this release; live polling is not yet enabled.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li>Registry internals: <code>crates/sharecli-fleet/src/registry.rs</code></li><li>Thermal governor: <code>crates/sharecli-fleet/src/thermal.rs</code></li></ul>`,32)])])}const k=s(n,[["render",r]]);export{g as __pageData,k as default};
